// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Animated Gradient Shader by melcom (www.melcom-music.de)

const vec3 color1 = vec3(0.004, 0.122, 0.153); // Farbe 1 / Color 1
const vec3 color2 = vec3(0.094, 0.212, 0.255); // Farbe 2 / Color 2
const vec3 color3 = vec3(0.149, 0.333, 0.404); // Farbe 3 / Color 3
const vec3 color4 = vec3(0.745, 0.863, 0.965); // Farbe 4 / Color 4

// Hauptfunktion für das Bild / Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy; // Normierung der UV-Koordinaten / Normalize UV coordinates

    float time = iTime * 0.5; // Geschwindigkeit des Farbverlaufs / Speed of the gradient

    // Animierter Farbverlauf / Animated gradient
    vec3 color = mix(color1, color4, uv.y + 0.5 * sin(time));

    fragColor = vec4(color, 1.0); // Setzen der finalen Fragmentfarbe / Setting the final fragment color
}
